    if let Some(actual) = origin.subnet_id() {
        let expected = misc::compute_subnet_for_data_column_sidecar(
            &self.chain_config,
            data_column_sidecar.index,
        );
        ensure!(
            actual == expected,
            Error::DataColumnSidecarOnIncorrectSubnet {
                data_column_sidecar,
                expected,
                actual,
            },
        );
    }

